import { useRef, useState } from 'react'
import { useHistory, useParams } from 'react-router'
import { Container, InnerForm, CustomText, InnerInput, Button } from '../../../../../components'
import StepsHeader from '../../../../../components/StepsHeader'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../../lang'
import { BottomActionContainerStyle } from '../../../../../commonStyle/index.style'
import { formatMoney } from '../../../../../helpers/utility'
import { PolicyContextProvider } from '../../../Policy/context'
import { PROPERTY_LANG } from '../../lang'
import { ownershipFormData, mapOwnershipApiData, insuredValueFormData, mapInsuredValueApiData, startDateFormData, mapStartDateApiData } from '../constants'
import useDraftApi from '../hooks/useDraftApi'
import { calculateEndDate, calculateSumInsured, formatDateToApi } from './helpers'
import { PropertyBuildingStyle } from './index.style'

function PropertyBuildingData () {
  const history = useHistory()
  const { draftId } = useParams()

  const ownershipFormRef = useRef()
  const insuredValueFormRef = useRef()
  const startDateFormRef = useRef()

  const [draftPolicyDetails, setDraftPolicyDetails] = useState({})
  const [insuredValues, setInsuredValues] = useState({
    building_value: 0,
    building_content_value: 0,
    machine_value: 0,
    equipment_value: 0,
    stock_value: 0,
    sum_insured: 0
  })

  const { isGetDraftLoader, isSaveLoader, handleSaveToDraft } = useDraftApi({
    draftId: draftId,
    onGetDraftDetailSuccess: (data) => {
      setDraftPolicyDetails(data.policy_details)
      setInsuredValues({
        building_value: data.policy_details?.property_data?.building_value || 0,
        building_content_value: data.policy_details?.property_data?.building_content_value || 0,
        machine_value: data.policy_details?.property_data?.machine_value || 0,
        equipment_value: data.policy_details?.property_data?.equipment_value || 0,
        stock_value: data.policy_details?.property_data?.stock_value || 0,
        sum_insured: calculateSumInsured(data.policy_details?.property_data)
      })
    },
    onSaveSuccess: ({ draftId }) => {
      history.push(`/property/property-protection/3/packages/${draftId}`)
    }
  })

  const handleOwnershipFormChange = (value) => {
    if (value.type) {
      // Update draftPolicyDetails for customer name check
      setDraftPolicyDetails({
        ...draftPolicyDetails,
        customer_data: { type: value.type }
      })
    }
  }

  const handleInsuredValueFormChange = (value, name) => {
    const newInsuredValues = { ...insuredValues }
    if (name) {
      newInsuredValues[name] = parseInt(value) || 0
    }
    newInsuredValues.sum_insured = calculateSumInsured(newInsuredValues)
    setInsuredValues(newInsuredValues)
  }

  const handleStartDateFormChange = (value, name) => {
    if (name === 'start_date') {
      const endDate = calculateEndDate(value)
      // Trigger UI update
      setDraftPolicyDetails({
        ...draftPolicyDetails,
        start_date: formatDateToApi(value),
        end_date: formatDateToApi(endDate)
      })
      // Trigger formData update
      startDateFormRef.current.handleDobChange(endDate, 'end_date')
    }
  }

  const handleFormSubmit = async (e) => {
    const ownershipFormData = await ownershipFormRef.current.handleSubmit(e)
    const insuredValueFormData = await insuredValueFormRef.current.handleSubmit(e)
    const startDateFormData = await startDateFormRef.current.handleSubmit(e)

    if (insuredValueFormData) {
      const finalData = {
        ...(draftPolicyDetails || {}),
        ...mapOwnershipApiData(ownershipFormData, draftPolicyDetails),
        ...mapInsuredValueApiData(insuredValueFormData, draftPolicyDetails, insuredValues.sum_insured),
        ...mapStartDateApiData(startDateFormData)
      }
      handleSaveToDraft(finalData, 'package_select', 'package_select')
    }
  }

  const renderTitleForBlock = (title) => {
    return (
      <CustomText
        size='16px'
        weight={800}
        bottom='10px'
        color={AgentColorPallette.mustard}
      >
        {title}
      </CustomText>
    )
  }

  return (
    <Container
      title={PROPERTY_LANG.propertyInsurance}
      loader={isGetDraftLoader || isSaveLoader}
      hideBottomTabs
      showCloseIcon
      onClose={() => history.push('/dashboard')}
      onBackClick={() => history.push(`/property/property-protection/1/form/${draftId}`)}
    >
      <PropertyBuildingStyle>
        <StepsHeader
          current='2'
          totalSteps='6'
          leftText={PROPERTY_LANG.buildingDataAndPolicyDate}
          className='steps-header'
        />
        <div className='building-form-container'>
          {renderTitleForBlock(PROPERTY_LANG.propertyOwnership)}
          <InnerForm
            formData={ownershipFormData(draftPolicyDetails)}
            onChangeSelect={handleOwnershipFormChange}
            ref={ownershipFormRef}
          />

          <hr className='separator' />

          {renderTitleForBlock(PROPERTY_LANG.buildingData)}
          <InnerForm
            formData={insuredValueFormData(draftPolicyDetails)}
            onInputChange={handleInsuredValueFormChange}
            ref={insuredValueFormRef}
          />
          <CustomText
            top='4px'
            bottom='4px'
            color={AgentColorPallette.fontSecondary}
          >
            {PROPERTY_LANG.totalSumInsured}
          </CustomText>
          <InnerInput
            name='sum_insured'
            value={formatMoney(insuredValues.sum_insured, 0)}
            disabled
            className='policy-end-date'
            placeholder={PROPERTY_LANG.totalSumInsured}
          />

          <hr className='separator' />

          {renderTitleForBlock(LANG_STRINGS.policyDate)}
          <InnerForm
            formData={startDateFormData(draftPolicyDetails)}
            onDobChange={handleStartDateFormChange}
            ref={startDateFormRef}
          />
        </div>
        <BottomActionContainerStyle padding='0'>
          <Button
            className='button-margin'
            onClick={handleFormSubmit}
            id='propertyStepSubmit_2'
          >
            {LANG_STRINGS.next}
          </Button>
        </BottomActionContainerStyle>
      </PropertyBuildingStyle>
    </Container>
  )
}

function WrappedPropertyBuildingData (props) {
  return (
    <PolicyContextProvider>
      <PropertyBuildingData {...props} />
    </PolicyContextProvider>
  )
}

export default WrappedPropertyBuildingData
